#![allow(unused_imports)]
use verus::prelude::*;

verus! {

    /// Given two equally‐long input vectors of i32, produce a new vector
    /// whose i‐th entry is the product of the i‐th entries of the inputs.
    fn element_wise_multiplication(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32>
        requires
            // The inputs must have the same length
            arr1.len() == arr2.len(),
        ensures
            // The result has the same length, and each element is the pointwise product
            |res: Vec<i32>| {
                res.len() == arr1.len() &&
                forall(|i: usize| i < res.len() ==> res[i] == arr1[i] * arr2[i])
            }
    {
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        // Loop over indices [0 .. arr1.len())
        while i < arr1.len() {
            // Invariant: i is the next index to process,
            // and we've already pushed i products into res.
            invariant i <= arr1.len();
            invariant res.len() == i;
            decreases arr1.len() - i;

            let x: i32 = arr1[i];
            let y: i32 = arr2[i];
            let prod: i32 = x * y;
            // By the problem assumption, x * y fits in i32 (no overflow).

            res.push(prod);
            i += 1;
        }

        res
    }

}